import time, random, sys
print(sys.version)
# Persistent treap with tuple nodes: (key, prio, size, left, right)
rnd = random.Random(12345)
prios = [rnd.getrandbits(30) for _ in range(400000)]
pi = [0]
def newprio():
    p = pi[0]; pi[0]+=1
    return prios[p % len(prios)]

def sz(t): return t[2] if t else 0

def mk(key, left, right):
    return (key, newprio(), 1+sz(left)+sz(right), left, right)

def split(t, key):
    # keys < key -> lo, >= key -> hi
    if not t: return (None, None)
    if t[0] < key:
        lo, hi = split(t[4], key)
        return (mk(t[0], t[3], lo), hi)
    else:
        lo, hi = split(t[3], key)
        return (lo, mk(t[0], hi, t[4]))

def merge(a, b):
    if not a: return b
    if not b: return a
    if a[1] > b[1]:
        return mk(a[0], a[3], merge(a[4], b))
    else:
        return mk(b[0], merge(a, b[3]), b[4])

def insert(t, key):
    if not t: return mk(key, None, None)
    if t[1] > prios[hash(key) % len(prios)] and False:
        pass
    if t[0] < key:
        return mk(t[0], t[3], insert(t[4], key))
    elif key < t[0]:
        return mk(t[0], insert(t[3], key), t[4])
    else:
        return t  # unique keys

def count_lt(t, key):
    c = 0
    while t:
        if t[0] < key:
            c += 1 + sz(t[3]); t = t[4]
        else:
            t = t[3]
    return c

N = 100000
t0 = time.perf_counter()
root = None
keys = list(range(N))
rnd.shuffle(keys)
for k in keys:
    root = insert(root, (k, k))
t1 = time.perf_counter()
print("insert 100k:", t1-t0)

t0 = time.perf_counter()
s = 0
for k in range(0, N, 7):
    s += count_lt(root, (k, -1))
t1 = time.perf_counter()
print("count_lt x", N//7, ":", t1-t0, s)

# split-based insert (2 traversals) vs 1 traversal above; test 32-insert refill pattern
t0 = time.perf_counter()
r2 = root
for i in range(30000):
    r2 = insert(r2, (N+i, i))
t1 = time.perf_counter()
print("30k more inserts:", t1-t0)

# delete via split
def delete(t, key):
    lo, rest = split(t, key)
    mid, hi = split(rest, (key[0], key[1]+1))
    return merge(lo, hi)

t0 = time.perf_counter()
r3 = r2
for i in range(0, 30000, 3):
    r3 = delete(r3, (N+i, i))
t1 = time.perf_counter()
print("10k deletes:", t1-t0)
